export const IANA_BY_NAME = {
  'France': 'Europe/Paris',
  'Norway': 'Europe/Oslo',
  'Kosovo': 'Europe/Belgrade',
  'Turkey': 'Europe/Istanbul',
  'Indian Ocean Territories': 'Indian/Chagos'
};

/**
 * Wraps longitude to the range [-180, 180)
 */
export function wrapLon(lon) {
  return ((lon + 180) % 360 + 360) % 360 - 180;
}

/**
 * Calculates a rough timezone identifier based on longitude.
 * Used as a fallback for ocean clicks or when no country is found.
 */
export function ianaFromLon(lon) {
  const hours = Math.round(wrapLon(lon) / 15);
  const inverted = -hours;
  if (inverted === 0) return 'Etc/UTC';
  return 'Etc/GMT' + (inverted > 0 ? '+' + inverted : inverted);
}

/**
 * Resolves a specific IANA timezone for countries with multiple timezones.
 */
export function resolveMultiTz(code, lat, lon) {
  const normalizedLon = wrapLon(lon);
  if (code === 'RU') {
    if (normalizedLon < 30) return 'Europe/Kaliningrad';
    if (normalizedLon < 49) return 'Europe/Moscow';
    if (normalizedLon < 53) return 'Europe/Samara';
    if (normalizedLon < 68) return 'Asia/Yekaterinburg';
    if (normalizedLon < 78) return 'Asia/Omsk';
    if (normalizedLon < 98) return 'Asia/Krasnoyarsk';
    if (normalizedLon < 114) return 'Asia/Irkutsk';
    if (normalizedLon < 130) return 'Asia/Yakutsk';
    if (normalizedLon < 143) return 'Asia/Vladivostok';
    if (normalizedLon < 160) return 'Asia/Magadan';
    return 'Asia/Kamchatka';
  }
  if (code === 'US') {
    if (lat > 51 && normalizedLon < -129) return 'America/Anchorage';
    if (normalizedLon < -172 || (lat < 30 && normalizedLon < -152 && normalizedLon > -179)) return 'Pacific/Honolulu';
    if (lat > 17 && lat < 23 && normalizedLon > -161 && normalizedLon < -154) return 'Pacific/Honolulu';
    if (normalizedLon < -115) return 'America/Los_Angeles';
    if (normalizedLon < -102) return 'America/Denver';
    if (normalizedLon < -87) return 'America/Chicago';
    if (normalizedLon < -64) return 'America/New_York';
    return 'America/Puerto_Rico';
  }
  if (code === 'CA') {
    if (normalizedLon < -120) return 'America/Vancouver';
    if (normalizedLon < -110) return 'America/Edmonton';
    if (normalizedLon < -90) return 'America/Winnipeg';
    if (normalizedLon < -77) return 'America/Toronto';
    if (lat > 60) return 'America/Iqaluit';
    return 'America/Halifax';
  }
  if (code === 'AU') {
    if (normalizedLon < 129) return 'Australia/Perth';
    if (normalizedLon < 138) return 'Australia/Darwin';
    if (normalizedLon < 141.5 && lat > -32) return 'Australia/Adelaide';
    if (lat < -39) return 'Australia/Hobart';
    return 'Australia/Sydney';
  }
  if (code === 'BR') {
    if (normalizedLon < -68) return 'America/Rio_Branco';
    if (normalizedLon < -54) return 'America/Manaus';
    return 'America/Sao_Paulo';
  }
  if (code === 'MX') {
    if (normalizedLon < -109) return 'America/Tijuana';
    if (normalizedLon < -102) return 'America/Chihuahua';
    return 'America/Mexico_City';
  }
  if (code === 'ID') {
    if (normalizedLon < 110) return 'Asia/Jakarta';
    if (normalizedLon < 125) return 'Asia/Makassar';
    return 'Asia/Jayapura';
  }
  if (code === 'KZ') {
    return 'Asia/Almaty';
  }
  if (code === 'CL') {
    if (lat < -48) return 'America/Punta_Arenas';
    if (normalizedLon < -90) return 'Pacific/Easter';
    return 'America/Santiago';
  }
  if (code === 'CD') {
    return normalizedLon < 22 ? 'Africa/Kinshasa' : 'Africa/Lubumbashi';
  }
  if (code === 'PT') {
    if (lat < 36) return 'Atlantic/Madeira';
    if (normalizedLon < -20) return 'Atlantic/Azores';
    return 'Europe/Lisbon';
  }
  if (code === 'ES') {
    if (lat < 30 && normalizedLon < -10) return 'Atlantic/Canary';
    return 'Europe/Madrid';
  }
  if (code === 'NZ') {
    if (normalizedLon > 175 || normalizedLon < -175) return 'Pacific/Chatham';
    return 'Pacific/Auckland';
  }
  if (code === 'GL') {
    if (normalizedLon > -20) return 'America/Danmarkshavn';
    if (normalizedLon > -45) return 'America/Nuuk';
    return 'America/Thule';
  }
  return null;
}

/**
 * Resolves an IANA timezone identifier based on coordinates and optional feature properties.
 */
export function resolveIana(lat, lon, props) {
  if (props) {
    const iso = String(props.iso_a2 || '');
    const named = IANA_BY_NAME[props.name];
    if (named) return named;
    const mapped = IANA_BY_ISO[iso];
    if (mapped) {
      if (mapped.indexOf('MULTI:') === 0) {
        return resolveMultiTz(mapped.slice(6), lat, lon) || ianaFromLon(lon);
      }
      return mapped;
    }
  }
  return ianaFromLon(lon);
}

/**
 * Formats the local time and UTC offset for a given IANA timezone.
 */
export function formatTimeFromIana(iana, date) {
  try {
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: iana,
      timeZoneName: 'shortOffset',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false
    }).formatToParts(date);

    const timeParts = parts.filter(p => ['hour', 'minute', 'second'].includes(p.type));
    const localTime = timeParts.map(p => p.value).join(':');

    let tzOffset = (parts.find(p => p.type === 'timeZoneName') || {}).value || 'UTC+0';
    tzOffset = tzOffset.replace('GMT', 'UTC').replace('UTC+0', 'UTC±0');
    tzOffset = tzOffset.replace(/UTC([+-])0(\d)/, 'UTC$1$2');
    if (tzOffset === 'UTC' || tzOffset === 'UTC±0') tzOffset = 'UTC+0';

    return { localTime, tzOffset };
  } catch(e) {
    const pad = (n) => String(n).padStart(2, '0');
    return {
      localTime: `${pad(date.getUTCHours())}:${pad(date.getUTCMinutes())}:${pad(date.getUTCSeconds())}`,
      tzOffset: 'UTC+0'
    };
  }
}
